head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



// 직전에 실행한 업로드 조건 (결과 확인 시 함께 출력)
scwin.strLastCond = "";

scwin.onpageload = function () {
    // 사전 조건은 dataList 정적 데이터로 세팅됨 (추가 처리 없음)
};



// ① startRowIndex = 0 / header = '0'
scwin.btn_readCSV_0_h0_onclick = function () {
    scwin.strLastCond = "① startRowIndex=0 / header='0'";
    grd_start.readCSV({ startRowIndex : 0, header : "0" });
};

// ② startRowIndex = 0 / header = '1'
scwin.btn_readCSV_0_h1_onclick = function () {
    scwin.strLastCond = "② startRowIndex=0 / header='1'";
    grd_start.readCSV({ startRowIndex : 0, header : "1" });
};

// ③ startRowIndex = 1 / header = '0'
scwin.btn_readCSV_1_h0_onclick = function () {
    scwin.strLastCond = "③ startRowIndex=1 / header='0'";
    grd_start.readCSV({ startRowIndex : 1, header : "0" });
};

// ④ startRowIndex = 1 / header = '1'
scwin.btn_readCSV_1_h1_onclick = function () {
    scwin.strLastCond = "④ startRowIndex=1 / header='1'";
    grd_start.readCSV({ startRowIndex : 1, header : "1" });
};



// GridView 에 반영된 Row 수와 첫번째 Column 값을 한 줄로 출력
scwin.btn_getResult_onclick = function () {
    var nCnt = grd_start.getRowCount();
    var arrRow = [];

    for (var i = 0; i < nCnt; i++) {
        var v1 = grd_start.getCellData(i, "c1");
        arrRow.push("(" + (v1 == null ? "" : v1) + ")");
    }

    scwin.setReturnValue(scwin.strLastCond + " → Row " + nCnt + " : " + arrRow.join(" "));
};
